const ALIASES = { noderepl: 'nodejs', apolloio: 'apollo', claudeai: 'claude' };
const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
const uri = (svg) => `data:image/svg+xml,${encodeURIComponent(svg)}`;

function keyFor(name) {
  const full = norm(name);
  if (LOGOS[full]) return full;
  if (ALIASES[full]) return ALIASES[full];
  // "Atlassian (Jira, Confluence, Compass)", "Claude Docs", "claude-in-chrome": the brand comes first
  const first = norm(String(name ?? '').split(/[\s(_.-]/)[0]);
  return LOGOS[first] ? first : null;
}

// The logo for a connector or service name (a dark-theme variant where the brand has one), or null.
export function logoFor(name) {
  const logo = LOGOS[keyFor(name)];
  if (!logo) return null;
  const img = h('img', { src: uri(logo.light), alt: '', width: '20', height: '20' });
  return logo.dark ? h('picture', {}, h('source', { srcset: uri(logo.dark), media: '(prefers-color-scheme: dark)' }), img) : img;
}
